import XCTest
import UIKit
@testable import G526CameraDrive

/// Kullanıcının kendi kamerasından alınmış gerçek kareler (960x540 gri, JPEG). Sentetik sahnelerin yakalayamadığı
/// durumları (kenarda ışık düşüşü, kalın yazı, kenarda kesik kart) gerçek veriyle denemek için.
enum RealFrames {
    /// İki kart yan yana, soldaki kartın yazısı çerçevenin sol kenarında kesik (video karesi 12)
    static let leftCutA = ""
    /// Aynı sahne, video karesi 36
    static let leftCutB = ""
    /// İki kart, ikisi de tam görünüyor (gerçek bir çekimden)
    static let bothFull = ""

    static func luma(_ base64: String) -> (px: [Float], w: Int, h: Int)? {
        guard let data = Data(base64Encoded: base64), let image = UIImage(data: data)?.cgImage else { return nil }
        let w = image.width
        let h = image.height
        var bytes = [UInt8](repeating: 0, count: w * h)
        let ok: Bool = bytes.withUnsafeMutableBytes { buf in
            guard let ctx = CGContext(data: buf.baseAddress, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w,
                                      space: CGColorSpaceCreateDeviceGray(), bitmapInfo: CGImageAlphaInfo.none.rawValue) else { return false }
            ctx.draw(image, in: CGRect(x: 0, y: 0, width: w, height: h))
            return true
        }
        if !ok { return nil }
        return (bytes.map { Float($0) }, w, h)
    }
}
